-- BA Client Ops Tracker v0.6.70: ONE-RUN FRESH DATABASE SETUP
-- Includes schema versions 1 through 18. Run this ENTIRE file once in Supabase SQL Editor.
-- Requires a NEW Supabase database with no existing BA Tracker tables.
-- Existing deployment / restored backup: DO NOT run this file. See database/README.md.
-- This creates schema and initial accounts, not a copy of your current data.
-- No default passwords: configure INTERNAL_ADMIN_BOOTSTRAP_PASSWORD and
-- BXI_CORE_BOOTSTRAP_PASSWORD on the app server (at least 12 characters each).
-- Generated by npm run db:bundle. Keep migration history; do not hand-edit this file.

begin;
select pg_advisory_xact_lock(hashtext('ba_client_ops_fresh_setup'));

do $setup_guard$
declare
  object_name text;
begin
  foreach object_name in array array['anon','authenticated','service_role'] loop
    if not exists (select 1 from pg_roles where rolname = object_name) then
      raise exception 'Supabase role % is missing. Use a new Supabase project for this setup.', object_name;
    end if;
  end loop;
  foreach object_name in array array['activity_logs','app_settings','app_users','audit_logs','clients','data_migration_runs','document_attachments','document_versions','documents','drf_error_logs','gmail_accounts','google_calendar_accounts','google_calendar_connections','inquiries','organizations','password_reset_tokens','planner_activities','platform_users','projects','task_statuses','tasks','tenant_ai_agents','tenant_dochub_accounts','tenant_dochub_documents','tenant_integrations','tenant_state','tenant_templates','tracker_state','user_communication_settings','user_communications'] loop
    if to_regclass(format('public.%I', object_name)) is not null then
      raise exception 'Fresh setup stopped: public.% already exists. No changes were applied. Use newer migrations for an existing installation; do not replay old migrations.', object_name;
    end if;
  end loop;
end;
$setup_guard$;

-- Included source: migrations/schema.sql
-- SHA-256: 4af4959e00b9d2b59031598c73da425c3c5eca59ca4a548c9fb81be1a659438b
-- BA Client Ops Tracker - single-workspace cloud state
-- Run this in Supabase SQL Editor once.

create table if not exists public.tracker_state (
  id text primary key,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

-- Direct browser access is intentionally disabled. The app's Node server uses
-- the Supabase service-role key and is the only component that reads/writes this table.
alter table public.tracker_state enable row level security;
revoke all on table public.tracker_state from anon, authenticated;

create or replace function public.touch_tracker_state_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists tracker_state_touch_updated_at on public.tracker_state;
create trigger tracker_state_touch_updated_at
before update on public.tracker_state
for each row execute function public.touch_tracker_state_updated_at();

