  generated_storage_path text,
  created_by text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);


create table if not exists public.document_versions (
  id uuid primary key default gen_random_uuid(),
  document_id uuid references public.documents(id) on delete cascade,
  version_number integer not null,
  storage_path text,
  snapshot jsonb not null default '{}'::jsonb,
  created_by text,
  created_at timestamptz not null default now(),
  unique(document_id, version_number)
);

create table if not exists public.document_attachments (
  id uuid primary key default gen_random_uuid(),
  document_id uuid references public.documents(id) on delete cascade,
  storage_path text not null,
  file_name text not null,
  mime_type text,
  file_size bigint,
  attachment_role text,
  uploaded_by text,
  uploaded_at timestamptz not null default now(),
  deleted_at timestamptz
);

-- The browser must never talk to these tables directly. The Node server uses the service role.
do $$
declare t text;
begin
  foreach t in array array['clients','projects','tasks','inquiries','activity_logs','planner_activities','app_users','task_statuses','app_settings','audit_logs','data_migration_runs','documents','document_versions','document_attachments']
  loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from anon, authenticated', t);
  end loop;
end $$;

-- Included source: migrations/schema-v3-multitenant.sql
-- SHA-256: 56e1ed3e8455e653d66ae34a4c50ff0f23fac5fad9e4aa9ff96aad6f9badcda7
-- BA Client Ops Tracker - Multi-tenant Architecture v3 (BXI-Core)
-- Run AFTER schema.sql and schema-v2.sql.
-- This keeps tracker_state as a legacy fallback, creates BXI-Core as the first tenant,
-- and moves the active workspace state to tenant_state without deleting existing data.

create extension if not exists pgcrypto;

create table if not exists public.organizations (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  slug text not null unique,
  status text not null default 'Active' check (status in ('Active','Suspended')),
  enabled_modules jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

create table if not exists public.tenant_state (
  organization_id uuid primary key references public.organizations(id) on delete cascade,
  data jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Stable ID for the original workspace so existing data can be migrated deterministically.
insert into public.organizations (id, name, slug, status, enabled_modules)
values (
  '00000000-0000-0000-0000-000000000001',
  'BXI-Core',
  'bxi-core',
  'Active',
  '["action","clients","projects","inbox","items","documents","reports","ai","settings"]'::jsonb
)
on conflict (id) do update set
  name = excluded.name,
  slug = excluded.slug,
  enabled_modules = excluded.enabled_modules,
  updated_at = now();

-- Preserve the existing single-workspace JSON state as the BXI-Core tenant state.
insert into public.tenant_state (organization_id, data, updated_at)
select '00000000-0000-0000-0000-000000000001', data, coalesce(updated_at, now())
from public.tracker_state
where id = 'main'
on conflict (organization_id) do update set
  data = excluded.data,
  updated_at = excluded.updated_at;

-- Tenant-scope every normalized table. Columns remain nullable during migration so old rows can be assigned safely.
alter table public.clients add column if not exists organization_id uuid references public.organizations(id);
alter table public.projects add column if not exists organization_id uuid references public.organizations(id);
alter table public.tasks add column if not exists organization_id uuid references public.organizations(id);
alter table public.inquiries add column if not exists organization_id uuid references public.organizations(id);
alter table public.activity_logs add column if not exists organization_id uuid references public.organizations(id);
alter table public.planner_activities add column if not exists organization_id uuid references public.organizations(id);
alter table public.app_users add column if not exists organization_id uuid references public.organizations(id);
alter table public.app_users add column if not exists is_platform_admin boolean not null default false;
alter table public.app_users add column if not exists last_login_at timestamptz;
alter table public.task_statuses add column if not exists organization_id uuid references public.organizations(id);
alter table public.app_settings add column if not exists organization_id uuid references public.organizations(id);
alter table public.audit_logs add column if not exists organization_id uuid references public.organizations(id);
alter table public.data_migration_runs add column if not exists organization_id uuid references public.organizations(id);
alter table public.documents add column if not exists organization_id uuid references public.organizations(id);
alter table public.document_versions add column if not exists organization_id uuid references public.organizations(id);
alter table public.document_attachments add column if not exists organization_id uuid references public.organizations(id);

-- Existing normalized rows all belong to the original BXI-Core workspace.
update public.clients set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.projects set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.tasks set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.inquiries set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.activity_logs set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.planner_activities set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.app_users set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.task_statuses set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.app_settings set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.audit_logs set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.data_migration_runs set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.documents set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.document_versions set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;
update public.document_attachments set organization_id = '00000000-0000-0000-0000-000000000001' where organization_id is null;

-- If app_users was not populated yet, recover user records from tracker_state/tenant_state.
insert into public.app_users (
  id, organization_id, username, password_hash, name, email, phone, role, modules, status,
  created_on, raw_data, is_platform_admin, updated_at, deleted_at
)
select
  account->>'id',
  '00000000-0000-0000-0000-000000000001',
  coalesce(account->>'username',''),
  coalesce(account->>'passwordHash',''),
  coalesce(account->>'name',''),
  coalesce(account->>'email',''),
  coalesce(account->>'phone',''),
  coalesce(account->>'role','Contributor'),
  coalesce(account->'modules','[]'::jsonb),
  coalesce(account->>'status','Active'),
  case when coalesce(account->>'createdAt','') ~ '^\d{4}-\d{2}-\d{2}$' then (account->>'createdAt')::date else current_date end,
  account - 'passwordHash',
  lower(coalesce(account->>'username','')) = 'admin',
  now(),
  null
from public.tenant_state state
cross join lateral jsonb_array_elements(coalesce(state.data->'accounts','[]'::jsonb)) account
where state.organization_id = '00000000-0000-0000-0000-000000000001'
  and coalesce(account->>'id','') <> ''
on conflict (id) do update set
  organization_id = excluded.organization_id,
  username = excluded.username,
  password_hash = case when excluded.password_hash <> '' then excluded.password_hash else public.app_users.password_hash end,
  name = excluded.name,
  email = excluded.email,
  phone = excluded.phone,
  role = excluded.role,
  modules = excluded.modules,
  status = excluded.status,
  raw_data = excluded.raw_data,
  is_platform_admin = public.app_users.is_platform_admin or excluded.is_platform_admin,
  updated_at = now(),
  deleted_at = null;

-- The original Admin account becomes the BXI-Core platform administrator.
update public.app_users
set is_platform_admin = true, organization_id = '00000000-0000-0000-0000-000000000001', updated_at = now()
where lower(username) = 'admin' and deleted_at is null;

-- Tenant-aware indexes.
create index if not exists clients_org_idx on public.clients(organization_id);
create index if not exists projects_org_idx on public.projects(organization_id);
create index if not exists tasks_org_idx on public.tasks(organization_id);
create index if not exists inquiries_org_idx on public.inquiries(organization_id);
create index if not exists activity_logs_org_idx on public.activity_logs(organization_id);
create index if not exists planner_activities_org_idx on public.planner_activities(organization_id);
create index if not exists app_users_org_idx on public.app_users(organization_id);
create index if not exists task_statuses_org_idx on public.task_statuses(organization_id);
create index if not exists app_settings_org_idx on public.app_settings(organization_id);
create index if not exists audit_logs_org_idx on public.audit_logs(organization_id, changed_at desc);
create index if not exists migration_runs_org_idx on public.data_migration_runs(organization_id, started_at desc);
create index if not exists documents_org_idx on public.documents(organization_id);
create index if not exists document_versions_org_idx on public.document_versions(organization_id);
create index if not exists document_attachments_org_idx on public.document_attachments(organization_id);

-- Keep direct browser access locked down. The Node server continues to use the service role.
alter table public.organizations enable row level security;
alter table public.tenant_state enable row level security;
revoke all on table public.organizations from anon, authenticated;
revoke all on table public.tenant_state from anon, authenticated;

-- Future-proof RLS helper for a later Supabase Auth phase. Without an organization_id JWT claim,
-- authenticated browser clients still see no tenant rows. The service role bypasses RLS.
create or replace function public.request_organization_id()
returns uuid
language plpgsql
stable
as $$
declare
  claims jsonb;
  value text;
begin
  begin
    claims := nullif(current_setting('request.jwt.claims', true), '')::jsonb;
    value := claims->>'organization_id';
    if value is null or value = '' then return null; end if;
    return value::uuid;
  exception when others then
    return null;
  end;
end;
$$;

-- Do not create permissive policies for app_users/platform data yet; the server is authoritative.
-- Tenant tables remain RLS-enabled and direct anon/authenticated grants remain revoked.

-- After assigning all legacy rows, organization ownership becomes mandatory.
alter table public.clients alter column organization_id set not null;
alter table public.projects alter column organization_id set not null;
alter table public.tasks alter column organization_id set not null;
alter table public.inquiries alter column organization_id set not null;
alter table public.activity_logs alter column organization_id set not null;
alter table public.planner_activities alter column organization_id set not null;
alter table public.app_users alter column organization_id set not null;
alter table public.task_statuses alter column organization_id set not null;
alter table public.app_settings alter column organization_id set not null;
alter table public.audit_logs alter column organization_id set not null;
alter table public.data_migration_runs alter column organization_id set not null;
alter table public.documents alter column organization_id set not null;
alter table public.document_versions alter column organization_id set not null;
alter table public.document_attachments alter column organization_id set not null;

-- Tenant isolation policies for a future Supabase Auth/JWT path. Current app traffic still goes
-- through the Node server/service role, while anon/authenticated table grants remain revoked.
do $$
declare
  t text;
begin
  foreach t in array array['clients','projects','tasks','inquiries','activity_logs','planner_activities','app_users','task_statuses','app_settings','audit_logs','data_migration_runs','documents','document_versions','document_attachments','tenant_state']
  loop
    execute format('drop policy if exists tenant_isolation on public.%I', t);
    execute format('create policy tenant_isolation on public.%I for all using (organization_id = public.request_organization_id()) with check (organization_id = public.request_organization_id())', t);
  end loop;
end $$;

drop policy if exists organization_self on public.organizations;
create policy organization_self on public.organizations
for select using (id = public.request_organization_id());

-- Included source: migrations/schema-v4-account-login.sql
-- SHA-256: bbcb93cd5a0a6b083158031bc051251f0ebb7d63f2dd2a19bc5030b1c91e66bb
-- BA Client Ops Tracker - Account-aware login + Internal Admin identity (v4)
-- Run AFTER schema-v3-multitenant.sql.
-- This separates the platform control-plane login from tenant users and allows
-- the same username (for example "admin") to exist in different tenant accounts.

create extension if not exists pgcrypto;

create table if not exists public.platform_users (
  id uuid primary key default gen_random_uuid(),
  account_key text not null default 'internal_admin',
  username text not null,
  password_hash text not null,
  name text not null default '',
  email text not null default '',
  phone text not null default '',
  status text not null default 'Active' check (status in ('Active','Disabled')),
  must_change_password boolean not null default true,
  password_changed_at timestamptz,
  last_login_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz
);

create unique index if not exists platform_users_account_username_uidx
  on public.platform_users(lower(account_key), lower(username))
  where deleted_at is null;

-- BXI-Core control-plane bootstrap user.
-- No default password is stored in SQL. The server initializes this account from
-- INTERNAL_ADMIN_BOOTSTRAP_PASSWORD on the first successful secure bootstrap login.
insert into public.platform_users (
  id, account_key, username, password_hash, name, status, must_change_password
)
values (
  '00000000-0000-0000-0000-000000000100',
  'internal_admin',
  'admin',
  '__BOOTSTRAP_REQUIRED__',
  'Internal Administrator',
  'Active',
  true
)
on conflict (id) do update set
  account_key = excluded.account_key,
  username = excluded.username,
  name = excluded.name,
  status = 'Active',
  updated_at = now();

-- Platform administration is no longer represented by a tenant app_users row.
-- The existing BXI-Core Admin remains a normal Administrator inside BXI-Core.
update public.app_users
set is_platform_admin = false, updated_at = now()
where is_platform_admin = true;

-- v2 originally made usernames globally unique. Account-aware login scopes them
-- to an organization, so Tenant A/admin and Tenant B/admin can coexist.
drop index if exists public.app_users_username_lower_uidx;
create unique index if not exists app_users_org_username_lower_uidx
  on public.app_users(organization_id, lower(username))
  where deleted_at is null;

-- Fresh-install safety: keep the original BXI-Core workspace usable even when
-- no tenant user existed before the multi-tenant migration. Existing data/users are untouched.
insert into public.app_users (
  id, organization_id, username, password_hash, name, email, phone, role, modules, status,
  created_on, raw_data, is_platform_admin, updated_at, deleted_at
)
select
  'admin',
  '00000000-0000-0000-0000-000000000001',
  'Admin',
  '__BOOTSTRAP_REQUIRED__',
  'Administrator', '', '', 'Administrator',
  '["action","clients","projects","inbox","items","documents","reports","ai","settings"]'::jsonb,
  'Active', current_date,
  '{"id":"admin","username":"Admin","name":"Administrator","email":"","phone":"","role":"Administrator","modules":["action","clients","projects","inbox","items","documents","reports","ai","settings"],"status":"Active"}'::jsonb,
  false, now(), null
where not exists (
  select 1 from public.app_users
  where organization_id = '00000000-0000-0000-0000-000000000001'
    and lower(username) = 'admin'
    and deleted_at is null
)
on conflict (id) do nothing;

-- Lock the platform identity table away from direct browser clients.
alter table public.platform_users enable row level security;
revoke all on table public.platform_users from anon, authenticated;

-- Included source: migrations/schema-v5-security-hardening.sql
-- SHA-256: 53a100b4533340d4a7b4036fc08599f3072cca6581062882447b8f50f4829ddd
-- BA Client Ops Tracker - Security hardening v5
-- Run AFTER schema-v4-account-login.sql.
-- This removes the known legacy "admin" bootstrap hash only when it is still unchanged.
-- Existing users with other SHA-256 hashes are left intact and are upgraded to bcrypt
-- automatically by the v0.6.2 server after their next successful login.


-- Internal Admin: replace the known default admin/admin hash with a bootstrap marker.
-- Set INTERNAL_ADMIN_BOOTSTRAP_PASSWORD (12+ characters) in Render before signing in.
update public.platform_users
set password_hash = '__BOOTSTRAP_REQUIRED__',
    must_change_password = true,
    updated_at = now()
where lower(account_key) = 'internal_admin'
  and lower(username) = 'admin'
  and password_hash = '8c6976e5b5410415bde908bd4dee15dfb167a9c873fc4bb8a81f6f2ab448a918'
  and must_change_password = true
  and deleted_at is null;

-- BXI-Core tenant Admin: remove the known default admin/admin hash when unchanged.
-- Set BXI_CORE_BOOTSTRAP_PASSWORD (12+ characters) in Render before signing in.
update public.app_users
set password_hash = '__BOOTSTRAP_REQUIRED__',
    updated_at = now()
where organization_id = '00000000-0000-0000-0000-000000000001'
  and lower(username) = 'admin'
  and password_hash = '8c6976e5b5410415bde908bd4dee15dfb167a9c873fc4bb8a81f6f2ab448a918'
  and deleted_at is null;

-- Keep BXI-Core tenant_state aligned so a later normalized sync cannot restore the old hash.
update public.tenant_state
set data = jsonb_set(
      data,
      '{accounts}',
      (
        select coalesce(jsonb_agg(
          case
            when lower(coalesce(account->>'username','')) = 'admin'
             and coalesce(account->>'passwordHash','') = '8c6976e5b5410415bde908bd4dee15dfb167a9c873fc4bb8a81f6f2ab448a918'
            then jsonb_set(account, '{passwordHash}', to_jsonb('__BOOTSTRAP_REQUIRED__'::text), true)
            else account
          end
        ), '[]'::jsonb)
        from jsonb_array_elements(coalesce(data->'accounts','[]'::jsonb)) account
      ),
      true
    ),
    updated_at = now()
where organization_id = '00000000-0000-0000-0000-000000000001';

-- Keep the legacy rollback snapshot aligned as well.
update public.tracker_state
set data = jsonb_set(
      data,
      '{accounts}',
      (
        select coalesce(jsonb_agg(
          case
            when lower(coalesce(account->>'username','')) = 'admin'
             and coalesce(account->>'passwordHash','') = '8c6976e5b5410415bde908bd4dee15dfb167a9c873fc4bb8a81f6f2ab448a918'
            then jsonb_set(account, '{passwordHash}', to_jsonb('__BOOTSTRAP_REQUIRED__'::text), true)
            else account
          end
        ), '[]'::jsonb)
        from jsonb_array_elements(coalesce(data->'accounts','[]'::jsonb)) account
      ),
      true
    )
where id = 'main';

-- Included source: migrations/schema-v6-tenant-save-integrity.sql
-- SHA-256: abbaa04a419c96a64927180d23e383647e4952d41038b72b5c9914e15b73be7c
-- BA Client Ops Tracker v0.6.3: atomic tenant saves and ownership checks.
-- Run AFTER schema-v5-security-hardening.sql, BEFORE starting v0.6.3.
-- Additive migration: existing records and credentials are not rewritten.

create or replace function public.save_tenant_state_v6(
  p_organization_id uuid,
  p_state jsonb,
  p_records jsonb default null,
  p_audit_entries jsonb default '[]'::jsonb,
  p_actor_id text default null,
  p_reason text default 'tracker-save'
)
returns jsonb
language plpgsql
security invoker
set search_path = public, pg_temp
as $$
declare
  tenant_status text;
  table_name text;
  collection_name text;
  row_data jsonb;
  ids text[];
  column_names text;
  update_columns text;
  requested integer;
  written integer;
  foreign_id boolean;
  counts jsonb := '{}'::jsonb;
  saved_at timestamptz := clock_timestamp();
  supported_tables text[] := array['clients','projects','tasks','inquiries','activity_logs','planner_activities','app_users','task_statuses','app_settings'];
begin
  if jsonb_typeof(p_state) is distinct from 'object' then
    raise exception 'A tracker data object is required.' using errcode = '22023';
  end if;

  -- Serialize saves within a workspace, including its compatibility snapshot.
  select status into tenant_status from public.organizations
  where id = p_organization_id and deleted_at is null for update;
  if not found or (p_records is not null and tenant_status <> 'Active') then
    raise exception 'The workspace is unavailable.' using errcode = '42501';
  end if;

  -- Validate the JSON snapshot before any write. Check items against BOTH tables
  -- so changing a Task into an Inquiry cannot evade ownership validation.
  for table_name, collection_name in
    select * from (values
      ('clients','clients'), ('projects','projects'), ('tasks','items'),
      ('inquiries','items'), ('activity_logs','activity'),
      ('planner_activities','planner'), ('app_users','accounts')
    ) as groups(table_name, collection_name)
  loop
    row_data := coalesce(p_state->collection_name, '[]'::jsonb);
    if jsonb_typeof(row_data) <> 'array' then
      raise exception 'Invalid % collection.', collection_name using errcode = '22023';
    end if;
    if exists (select 1 from jsonb_array_elements(row_data) entry
               where jsonb_typeof(entry) <> 'object' or coalesce(entry->>'id','') = '') then
      raise exception 'Every record must have an ID.' using errcode = '22023';
    end if;
    select coalesce(array_agg(entry->>'id'), array[]::text[]) into ids from jsonb_array_elements(row_data) entry;
    if cardinality(ids) <> (select count(distinct id) from unnest(ids) id) then
      raise exception 'Duplicate record IDs are not allowed.' using errcode = '22023';
    end if;
    execute format('select exists (select 1 from public.%I where id = any($1) and organization_id <> $2)', table_name)
      into foreign_id using ids, p_organization_id;
    if foreign_id then
      raise exception 'A record ID belongs to another workspace. No changes were saved.' using errcode = '42501';
    end if;
  end loop;

  if p_records is not null then
    if jsonb_typeof(p_records) <> 'object'
       or exists (select 1 from jsonb_object_keys(p_records) key where not (key = any(supported_tables)))
       or (select count(*) from jsonb_object_keys(p_records)) <> cardinality(supported_tables) then
      raise exception 'A complete normalized record set is required.' using errcode = '22023';
    end if;

    foreach table_name in array supported_tables loop
      row_data := p_records->table_name;
      if jsonb_typeof(row_data) is distinct from 'array' then
        raise exception 'Invalid normalized records.' using errcode = '22023';
      end if;
      requested := jsonb_array_length(row_data);
      select coalesce(array_agg(entry->>'id'), array[]::text[]) into ids from jsonb_array_elements(row_data) entry;
      if cardinality(ids) <> (select count(distinct id) from unnest(ids) id) then
        raise exception 'Duplicate record IDs are not allowed.' using errcode = '22023';
      end if;

      if requested > 0 then
        -- Only the privileged Node server can invoke this RPC. Its fixed record
        -- mappings select application columns; tenant ownership is assigned here.
        select string_agg(format('%I', key), ',' order by key),
               string_agg(format('%1$I = excluded.%1$I', key), ',' order by key) filter (where key <> 'id')
          into column_names, update_columns
          from jsonb_object_keys(row_data->0) key
          where key not in ('organization_id','created_at','updated_at','deleted_at','is_platform_admin');
        execute format(
          'insert into public.%1$I (%2$s,organization_id,updated_at,deleted_at)
           select %2$s,$2,$3,null from jsonb_populate_recordset(null::public.%1$I,$1)
           on conflict (id) do update set %3$s,updated_at=excluded.updated_at,deleted_at=null
           where %1$I.organization_id = excluded.organization_id',
          table_name, column_names, update_columns
        ) using row_data, p_organization_id, saved_at;
        get diagnostics written = row_count;
        -- Also protects a new-ID collision that occurs after the snapshot check.
        if written <> requested then
          raise exception 'A record ID belongs to another workspace. No changes were saved.' using errcode = '42501';
        end if;
      end if;

      execute format('update public.%I set deleted_at=$3,updated_at=$3 where organization_id=$2 and deleted_at is null and not (id = any($1))', table_name)
        using ids, p_organization_id, saved_at;
      counts := counts || jsonb_build_object(table_name, requested);
    end loop;

    insert into public.data_migration_runs (id,organization_id,status,reason,started_at,completed_at,started_by,counts)
    values (gen_random_uuid(),p_organization_id,'completed',p_reason,saved_at,saved_at,p_actor_id,counts);
  end if;

  insert into public.audit_logs
    (id,organization_id,entity_type,entity_id,action,changed_fields,before_data,after_data,changed_by,changed_by_name,source)
  select id,p_organization_id,entity_type,entity_id,action,changed_fields,before_data,after_data,changed_by,changed_by_name,source
  from jsonb_populate_recordset(null::public.audit_logs,coalesce(p_audit_entries,'[]'::jsonb));

  insert into public.tenant_state (organization_id,data,updated_at)
  values (p_organization_id,p_state,saved_at)
  on conflict (organization_id) do update set data=excluded.data,updated_at=excluded.updated_at;

  if p_organization_id = '00000000-0000-0000-0000-000000000001' then
    insert into public.tracker_state (id,data,updated_at) values ('main',p_state,saved_at)
    on conflict (id) do update set data=excluded.data,updated_at=excluded.updated_at;
  end if;

  return jsonb_build_object('ready',true,'syncedAt',saved_at,'counts',counts);
end;
$$;

-- This function accepts trusted server payloads. Never expose it to browsers.
revoke all on function public.save_tenant_state_v6(uuid,jsonb,jsonb,jsonb,text,text) from public, anon, authenticated;
grant execute on function public.save_tenant_state_v6(uuid,jsonb,jsonb,jsonb,text,text) to service_role;

-- Included source: migrations/schema-v7-password-recovery.sql
-- SHA-256: b5e3da5811af7272fa319c2cd5ebb9452c5cf96ae03ad26a6fe2a4d77d8db428
-- BA Client Ops Tracker v0.6.4. Run after schema-v6-tenant-save-integrity.sql.
-- Recovery tokens are private to the server. Existing accounts/data are retained.

create table if not exists public.password_reset_tokens (
  token_hash text primary key check (token_hash ~ '^[a-f0-9]{64}$'),
  account_type text not null check (account_type in ('tenant', 'platform')),
  user_id text not null,
  organization_id uuid references public.organizations(id) on delete cascade,
  credential_fingerprint text not null,
  email text not null,
  requested_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null default (clock_timestamp() + interval '30 minutes'),
  consumed_at timestamptz,
  check ((account_type = 'tenant' and organization_id is not null)
      or (account_type = 'platform' and organization_id is null))
);
create index if not exists password_reset_user_idx
  on public.password_reset_tokens(account_type, user_id, requested_at desc);
alter table public.password_reset_tokens enable row level security;
revoke all on public.password_reset_tokens from public, anon, authenticated;
grant all on public.password_reset_tokens to service_role;

create or replace function public.issue_password_reset_v7(
  p_account text, p_username text, p_email text, p_token_hash text
) returns jsonb
language plpgsql security invoker set search_path = public, pg_temp
as $$
declare
  target_org uuid;
  target_user text;
  target_type text;
  target_email text;
  target_hash text;
  account_label text;
begin
  if p_token_hash is null or p_token_hash !~ '^[a-f0-9]{64}$' then
    raise exception 'Invalid token hash.' using errcode = '22023';
  end if;
  if lower(replace(trim(p_account), ' ', '_')) = 'internal_admin' then
    target_type := 'platform';
    account_label := 'Internal Admin';
    select id::text, email, password_hash into target_user, target_email, target_hash
      from public.platform_users
      where account_key = 'internal_admin' and lower(username) = lower(trim(p_username))
        and status = 'Active' and deleted_at is null
      for update;
  else
    target_type := 'tenant';
    -- Same lock order as tenant saves: organization, then user, then tokens.
    select id, name into target_org, account_label from public.organizations
      where (lower(slug) = lower(trim(p_account)) or lower(name) = lower(trim(p_account)))
        and status = 'Active' and deleted_at is null
      order by id limit 1 for update;
    if target_org is null then return null; end if;
    select id, email, password_hash into target_user, target_email, target_hash
      from public.app_users
      where organization_id = target_org and lower(username) = lower(trim(p_username))
        and status = 'Active' and deleted_at is null
      for update;
  end if;
  if target_user is null or nullif(trim(target_email), '') is null
      or lower(trim(target_email)) <> lower(trim(p_email)) then return null; end if;
  -- Limits follow the account across client IPs and app instances.
  if exists (select 1 from public.password_reset_tokens
      where account_type = target_type and user_id = target_user
        and requested_at > clock_timestamp() - interval '60 seconds')
    or (select count(*) from public.password_reset_tokens
      where account_type = target_type and user_id = target_user
        and requested_at > clock_timestamp() - interval '1 hour') >= 5 then return null; end if;

  delete from public.password_reset_tokens where expires_at < clock_timestamp() - interval '1 day';
  update public.password_reset_tokens set consumed_at = clock_timestamp()
    where account_type = target_type and user_id = target_user and consumed_at is null;
  insert into public.password_reset_tokens
    (token_hash, account_type, user_id, organization_id, credential_fingerprint, email)
    values (p_token_hash, target_type, target_user, target_org,
      encode(sha256(convert_to(target_hash, 'UTF8')), 'hex'), lower(trim(target_email)));
  return jsonb_build_object('email', trim(target_email), 'account', account_label);
end;
$$;

create or replace function public.redeem_password_reset_v7(p_token_hash text, p_password_hash text)
returns jsonb
language plpgsql security invoker set search_path = public, pg_temp
as $$
declare
  reset_row public.password_reset_tokens%rowtype;
  current_hash text;
  current_email text;
  account_row public.app_users%rowtype;
  snapshot jsonb;
  next_accounts jsonb;
  saved_at timestamptz := clock_timestamp();
begin
  if p_password_hash is null or p_password_hash !~ '^\$2[aby]\$12\$[./A-Za-z0-9]{53}$' then
    raise exception 'A secure password hash is required.' using errcode = '22023';
  end if;
  select * into reset_row from public.password_reset_tokens where token_hash = p_token_hash;
  if not found then return null; end if;
  if reset_row.account_type = 'tenant' then
    perform 1 from public.organizations where id = reset_row.organization_id
      and status = 'Active' and deleted_at is null for update;
    if not found then return null; end if;
    select * into account_row from public.app_users
      where id = reset_row.user_id and organization_id = reset_row.organization_id
        and status = 'Active' and deleted_at is null for update;
    if not found then return null; end if;
    current_hash := account_row.password_hash;
    current_email := account_row.email;
  else
    select password_hash, email into current_hash, current_email from public.platform_users
      where id::text = reset_row.user_id and status = 'Active' and deleted_at is null for update;
    if not found then return null; end if;
  end if;
  -- Re-read under lock. Concurrent submissions can succeed only once.
  select * into reset_row from public.password_reset_tokens where token_hash = p_token_hash for update;
  if not found or reset_row.consumed_at is not null or reset_row.expires_at <= clock_timestamp()
      or reset_row.credential_fingerprint is distinct from encode(sha256(convert_to(current_hash, 'UTF8')), 'hex')
      or reset_row.email is distinct from lower(trim(current_email)) then return null; end if;

  if reset_row.account_type = 'platform' then
    update public.platform_users set password_hash = p_password_hash,
      must_change_password = false, password_changed_at = saved_at, updated_at = saved_at
      where id::text = reset_row.user_id;
  else
    update public.app_users set password_hash = p_password_hash, updated_at = saved_at where id = reset_row.user_id;
    -- Keep every server-side credential snapshot consistent in the same transaction.
    select data into snapshot from public.tenant_state where organization_id = reset_row.organization_id for update;
    snapshot := coalesce(snapshot, jsonb_build_object('schemaVersion', 5, 'clients', '[]'::jsonb,
      'projects', '[]'::jsonb, 'items', '[]'::jsonb, 'activity', '[]'::jsonb, 'planner', '[]'::jsonb));
    select coalesce(jsonb_agg(case when item->>'id' = reset_row.user_id
      then jsonb_set(item, '{passwordHash}', to_jsonb(p_password_hash)) else item end order by ordinal), '[]'::jsonb)
      into next_accounts from jsonb_array_elements(coalesce(snapshot->'accounts', '[]'::jsonb)) with ordinality a(item, ordinal);
    if not exists (select 1 from jsonb_array_elements(next_accounts) a where a->>'id' = reset_row.user_id) then
      next_accounts := next_accounts || jsonb_build_array(jsonb_build_object(
        'id', account_row.id, 'username', account_row.username, 'passwordHash', p_password_hash,
        'name', account_row.name, 'email', account_row.email, 'phone', account_row.phone,
        'role', account_row.role, 'modules', account_row.modules, 'status', account_row.status,
        'createdAt', account_row.created_on, 'theme', coalesce(account_row.raw_data->'theme', '"default"'::jsonb)));
    end if;
    snapshot := jsonb_set(snapshot, '{accounts}', next_accounts);
    insert into public.tenant_state(organization_id, data, updated_at) values(reset_row.organization_id, snapshot, saved_at)
      on conflict(organization_id) do update set data = excluded.data, updated_at = excluded.updated_at;
    if reset_row.organization_id = '00000000-0000-0000-0000-000000000001'::uuid then
      insert into public.tracker_state(id, data, updated_at) values('main', snapshot, saved_at)
        on conflict(id) do update set data = excluded.data, updated_at = excluded.updated_at;
    end if;
  end if;
  update public.password_reset_tokens set consumed_at = saved_at
    where account_type = reset_row.account_type and user_id = reset_row.user_id and consumed_at is null;
  return jsonb_build_object('userId', reset_row.user_id, 'accountType', reset_row.account_type,
    'organizationId', reset_row.organization_id);
end;
$$;

revoke all on function public.issue_password_reset_v7(text,text,text,text) from public, anon, authenticated;
revoke all on function public.redeem_password_reset_v7(text,text) from public, anon, authenticated;
grant execute on function public.issue_password_reset_v7(text,text,text,text) to service_role;
grant execute on function public.redeem_password_reset_v7(text,text) to service_role;

